function Config.PartnerData.data_partner_lev_fun(slot0)
	slot1 = Config.PartnerData.data_partner_lev[slot0]

	if DATA_DEBUG and slot1 == nil then
		print("(Config.PartnerData.data_partner_lev[" .. slot0 .. "])not found")

		return
	end

	return slot1
end

