function Config.PartnerData.data_partner_brach_fun(slot0)
	slot1 = Config.PartnerData.data_partner_brach[slot0]

	if DATA_DEBUG and slot1 == nil then
		print("(Config.PartnerData.data_partner_brach[" .. slot0 .. "])not found")

		return
	end

	return slot1
end

Config.PartnerData.data_partner_star_length = 2216
Config.PartnerData.data_partner_star_cache = {}

function Config.PartnerData.data_partner_star(slot0)
	if Config.PartnerData.data_partner_star_cache[slot0] == nil then
		if not Config.PartnerData.data_partner_star_table[slot0] then
			return
		end

		if not loadstring(string.format("return %s", slot1))() then
			return
		end

		Config.PartnerData.data_partner_star_cache[slot0] = {
			bid = slot1[1],
			star = slot1[2],
			res_id = slot1[3],
			head_id = slot1[4],
			add_hp = slot1[5],
			add_atk = slot1[6],
			add_def = slot1[7],
			add_speed = slot1[8],
			attr = slot1[9],
			expend1 = slot1[10],
			expend2 = slot1[11],
			expend3 = slot1[12],
			other_expend = slot1[13],
			skills = slot1[14],
			lev_max = slot1[15],
			is_show = slot1[16],
			is_show_pokedex = slot1[17],
			attr_show = slot1[18],
			show_effect = slot1[19],
			fight_effect = slot1[20],
			source = slot1[21]
		}
	end

	return Config.PartnerData.data_partner_star_cache[slot0]
end

