function Config.PartnerData.data_get_compound_info_fun(slot0)
	slot1 = Config.PartnerData.data_get_compound_info[slot0]

	if DATA_DEBUG and slot1 == nil then
		print("(Config.PartnerData.data_get_compound_info[" .. slot0 .. "])not found")

		return
	end

	return slot1
end

