function Config.PartnerData.data_partner_buy_fun(slot0)
	slot1 = Config.PartnerData.data_partner_buy[slot0]

	if DATA_DEBUG and slot1 == nil then
		print("(Config.PartnerData.data_partner_buy[" .. slot0 .. "])not found")

		return
