Config.PartnerData.data_partner_show_length = 730
Config.PartnerData.data_partner_show_cache = {}

function Config.PartnerData.data_partner_show(slot0)
	if Config.PartnerData.data_partner_show_cache[slot0] == nil then
		if not Config.PartnerData.data_partner_show_table[slot0] then
			return
		end

		if not loadstring(string.format("return %s", slot1))() then
			return
		end

		Config.PartnerData.data_partner_show_cache[slot0] = {
			bid = slot1[1],
			lev = slot1[2],
			star = slot1[3],
			atk = slot1[4],
			def = slot1[5],
			hp = slot1[6],
			speed = slot1[7],
			crit_rate = slot1[8],
			crit_ratio = slot1[9],
			hit_magic = slot1[10],
			dodge_magic = slot1[11],
			tenacity = slot1[12],
			hit_rate = slot1[13],
			res = slot1[14],
			dodge_rate = slot1[15],
			cure = slot1[16],
			be_cure = slot1[17],
			dam = slot1[18],
			skills = slot1[19]
		}
	end

	return Config.PartnerData.data_partner_show_cache[slot0]
end

