Config.PartnerData.data_partner_library_length = 167
Config.PartnerData.data_partner_library_cache = {}

function Config.PartnerData.data_partner_library(slot0)
	if Config.PartnerData.data_partner_library_cache[slot0] == nil then
		if not Config.PartnerData.data_partner_library_table[slot0] then
			return
		end

		if not loadstring(string.format("return %s", slot1))() then
			return
		end

		Config.PartnerData.data_partner_library_cache[slot0] = {
			bid = slot1[1],
			title = slot1[2],
			voice_str = slot1[3],
			story = slot1[4],
			draw_offset = slot1[5],
			scale = slot1[6]
		}
	end

	return Config.PartnerData.data_partner_library_cache[slot0]
end

