	[40504.0] = "{40504, \"海军第一人\", \"你真是大闹了一番啊。\", \"\", {{40,60}}, 85}",
	[70524.0] = "{70524, \"炎帝\", \"各位，龙年大吉哟~\", \"\", {{-50,30}}, 75}",
	[70528.0] = "{70528, \"杰尔马统帅\", \"这个世界不需要同情，还有弱者\", \"\", {{-50,30}}, 75}",
	[70505.0] = "{70505, \"鱼鱼果实·幻兽种·青龙形态\", \"我才是最强的男人！！！\", \"，百兽海贼团总督，原新世界的“四皇”之一，被蒙奇·D·路飞击败后被剥夺四皇称号。实力极其强悍，拥有超乎想象的防御力和生命力，被称为“最强的生物”\", {{-25,80}}, 65}",
	[70532.0] = "{70532, \"地狱之王\", \"路飞是要成为海贼王的男人~！\", \"\", {{-50,30}}, 75}",
	[30304.0] = "{30304, \"Mr.5\", \"\", \"\", {}, 0}",
	[10504.0] = "{10504, \"黑帮老大\", \"让开吧，小哥们~\", \"\", {{0,20}}, 80}",
	[70520.0] = "{70520, \"改造人\", \"super！！！！\", \"\", {{-50,30}}, 75}",
	[50512.0] = "{50512, \"最强生物\", \"你说你想要成为什么？\", \"\", {{-25,80}}, 65}",
	[40403.0] = "{40403, \"CP9\", \"额~那个~那个其实~罗宾是我妹妹~\", \"\", {{0,30}}, 80}",
	[30101.0] = "{30101, \"强者海贼1号\", \"\", \"\", {}, 0}",
	[50506.0] = "{50506, \"地狱剑士\", \"你猜的不错，莫利亚，我得到了一个不错的能力....\", \"\", {{30,60}}, 70}",
	[30514.0] = "{30514, \"时光迁跃者\", \"我从800年穿越而来，你就是我旅途的终点！\", \"\", {{40,0}}, 65}",
	[50517.0] = "{50517, \"疫灾\", \"不要为我求情，我无所谓！\", \"\", {{-25,80}}, 65}",
	[10503.0] = "{10503, \"古龙种\", \"已经回不去了吗？\", \"\", {{0,50}}, 50}",
	[30508.0] = "{30508, \"和国剑豪\", \"曾经传说中武士腰间的名刀秋水，你做它的主人，也是这把刀的夙愿吧！\", \"\", {{0,90}}, 65}",
	[70513.0] = "{70513, \"五老星(土星)\", \"妄想挑战世界政府，就是死路一条\", \"世界贵族“天龙人”，外界所认知的世界政府最高权力“五老星”中的科学防卫武神，受到伊姆的直接管辖。\", {{-25,80}}, 65}",
	[70501.0] = "{70501, \"剑豪\", \"干嘛啊，想问路吗？\", \"\", {{-25,80}}, 65}",
	[70503.0] = "{70503, \"橡胶果实\", \"我是要成为海贼王的男人！\", \"小时候因误食了橡胶果实（人人果实·幻兽种·尼卡形态），而获得了如橡胶般自由伸缩的能力 。在香克斯的启蒙下，萌生了找到传说中的One Piece，成为海贼王的梦想 。口头禅是“我是要成为海贼王的男人”\", {{-25,80}}, 65}",
	[50502.0] = "{50502, \"冥王\", \"我是巴希尔·雷利，请多指教。\", \"\", {{-10,50}}, 85}",
	[30512.0] = "{30512, \"野心梦想家\", \"人的梦想，永远不会结束！\", \"\", {{40,0}}, 65}",
	[70515.0] = "{70515, \"饼干将星\", \"甜点三将星\", \"四皇之一“BIG MOM”夏洛特·玲玲的第十子（第15个孩子），与第六女夏洛特·卡斯塔德、第七女夏洛特·安洁露是龙凤胎。BIG MOM海贼团的最高干部“甜点三将星”之一，托特兰王国的饼干大臣，驻地是饼干岛的曲奇镇 [4] 。超人系恶魔果实饼干果实能力者，饼干人，悬赏金为8亿6000万贝里。平时藏在制造的饼干战士之中，自称“饼干骑士”，因此大多数人都不知道他的真面目，以至于悬赏令上的肖像画都是饼干战士\", {{-50,30}}, 75}",
	[10502.0] = "{10502, \"草帽兄长\", \"我是火拳艾斯，记住我\", \"\", {{-5,30}}, 80}",
	[50516.0] = "{50516, \"旱灾\", \"把船给老子靠上去！\", \"\", {{-25,80}}, 65}",
	[20511.0] = "{20511, \"草帽舵手\", \"这里交给老夫了！\", \"\", {{20,60}}, 65}",
	[10405.0] = "{10405, \"克罗马利蒙\", \"来吧，看看谁的拳头更快？！\", \"\", {{20,20}}, 85}",
	[70507.0] = "{70507, \"传说大海贼\", \"我才是传说中的大海贼！\", \"金狮子”史基，飘飘果实能力者，飘浮人，能浮游自己或物件在空中飞行，而得到“飞天海贼”（空飞ぶ海贼）的绰号，但对除了自己以外的生命体都不起作用。飞空海贼团船长－金狮子海贼舰队提督，是曾与哥尔·D·罗杰和“白胡子”爱德华·纽盖特齐名的传说中的大海贼。同时是推进城历史上第一位逃脱的海贼。持有的两把名剑“樱十”和“木枯”\", {{-25,80}}, 65}",
	[20402.0] = "{20402, \"娜美\", \"宝物，宝物！\", \"\", {{-20,50}}, 80}",
	[70512.0] = "{70512, \"猫蝮蛇老大\", \"老子就是鲸鱼森林守护神\", \"猫种毛皮族，佐乌岛毛茸茸公国两位国王之一，是掌管着黑夜的“黑夜之王”，与白昼之王犬岚齐名，被称为“猫蝮蛇老大”，自称“老子”。活跃时间为晚上六点至早上六点，其他时间都会陷入沉睡。猫蝮蛇率领着手下的“侠客团”，一起守护着毛皮族圣地“鲸鱼森林”，被称为“鲸鱼森林守护神”  。与犬岚过去同是和之国九里大名光月御田的家臣，赤鞘九人男之一，曾随御田加入过白胡子海贼团以及罗杰海贼团。御田死后，回到毛茸茸公国，以黑夜之王的身份治理毛茸茸公国\", {{-25,80}}, 65}",
	[70543.0] = "{70543, \"大妈\", \"Stay or Life？\", \"\", {{-50,30}}, 75}",
	[50401.0] = "{50401, \"狡诈猎人\", \"洛克船长吗？我三年前已经不用这个名字了~\", \"\", {{-30,60}}, 85}",
	[20401.0] = "{20401, \"冰山\", \"拿好这个设计图，快点走！\", \"\", {{-20,0}}, 70}",
	[20305.0] = "{20305, \"\", \"\", \"\", {}, 0}",
