	[20303.0] = "{20303, \"\", \"\", \"\", {}, 0}",
	[70504.0] = "{70504, \"人人果实·幻兽种·尼卡形态\", \"任何人都不许伤害我的伙伴！\", \"人人果实·幻兽种·尼卡形态的最终形态，借此形态打败了四皇之一的凯多\", {{-25,80}}, 65}",
	[20302.0] = "{20302, \"\", \"\", \"\", {}, 0}",
